package com.example.puller.repository;import com.example.puller.entity.OutboxEvent;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import javax.persistence.LockModeType;import java.util.*;public interface OutboxRepository extends JpaRepository<OutboxEvent,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select e from OutboxEvent e where e.status='NEW' order by e.id")List<OutboxEvent> findNewForUpdate(Pageable pageable);List<OutboxEvent> findByStatusAndLockedAtBefore(String status,Date cutoff);}
